const transcript = $json.transcript;

// Mask email addresses
const maskedEmail = transcript.replace(
  /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
  '[EMAIL_REDACTED]'
);

// Mask Indian phone numbers
const maskedPhone = maskedEmail.replace(
  /(?:\+91[\s-]?)?[6-9]\d{9}\b/g,
  '[PHONE_REDACTED]'
);

return [
  {
    json: {
      meeting_title: $json.meeting_title,
      clean_transcript: maskedPhone
    }
  }
];

const transcript = $json.clean_transcript;
const chunkSize = 1500;

const chunks = [];

for (let i = 0; i < transcript.length; i += chunkSize) {
  chunks.push({
    json: {
      meeting_title: $json.meeting_title,
      chunk_id: `chunk_${chunks.length + 1}`,
      chunk_text: transcript.slice(i, i + chunkSize)
    }
  });
}

return chunks;

const message = $json.text || "";

const lines = message
  .split("\n")
  .map(line => line.trim())
  .filter(line => line !== "");

let meetingTitle = "Untitled Meeting";
let transcriptLines = lines;

// If first line does NOT look like a speaker line,
// treat it as the meeting title.
if (
  lines.length > 0 &&
  !lines[0].match(/^[A-Za-z\s]+:/)
) {
  meetingTitle = lines[0];
  transcriptLines = lines.slice(1);
}

const transcript = transcriptLines.join("\n");

return [
  {
    json: {
      meeting_title: meetingTitle,
      transcript: transcript
    }
  }
];

const raw = $input.first().json['PRD Doc']

if (!raw) {
  throw new Error("Final PRD text not found");
}

let text = String(raw).trim();

// --------------------------------------------------
// BASIC CLEANUP
// --------------------------------------------------

// Remove accidental code fences
text = text.replace(/^```(?:markdown|text)?\s*/i, "");
text = text.replace(/\s*```$/i, "");

// Remove Markdown headings if AI accidentally creates them
text = text.replace(
  /^#{1,6}\s+(.+)$/gm,
  '*$1*'
);

// Convert Markdown bold to Slack bold
text = text.replace(
  /\*\*(.*?)\*\*/g,
  '*$1*'
);

// Remove non-breaking spaces
text = text.replace(/\u00A0/g, " ");

// Remove tabs
text = text.replace(/\t/g, " ");

// Remove accidental Slack timestamps
text = text.replace(
  /^\[\d{1,2}:\d{2}\s*(?:AM|PM)\]\s*$/gmi,
  ""
);

// Remove excessive blank lines
text = text.replace(/\n{3,}/g, "\n\n");


// --------------------------------------------------
// FORMAT TWO-COLUMN SECTIONS
// --------------------------------------------------

function formatTwoColumnSection(text, sectionName, labelName) {

  const regex = new RegExp(
    `\\*${sectionName}\\*\\s*\\n([\\s\\S]*?)(?=\\n\\*[^\\n]+\\*|$)`,
    "i"
  );

  const match = text.match(regex);

  if (!match) {
    return text;
  }

  const rows = match[1]
    .split("\n")
    .map(line => line.trim())
    .filter(line => line.includes("|"));

  if (rows.length === 0) {
    return text;
  }

  const formattedRows = rows.map(row => {

    const parts = row.split("|");

    const column1 = (parts[0] || "").trim();

    const column2 = parts
      .slice(1)
      .join("|")
      .trim();

    if (!column1 || !column2) {
      return "";
    }

    return `*${labelName}:* ${column1}\n*Description:* ${column2}`;
  })
  .filter(Boolean);

  const replacement =
    `*${sectionName}*\n\n` +
    formattedRows.join("\n\n");

  return text.replace(match[0], replacement);
}


// --------------------------------------------------
// SUCCESS METRICS
// --------------------------------------------------

text = formatTwoColumnSection(
  text,
  "SUCCESS METRICS",
  "Metric"
);


// --------------------------------------------------
// EPICS
// --------------------------------------------------

text = formatTwoColumnSection(
  text,
  "EPICS",
  "Epic"
);


// --------------------------------------------------
// FEATURES
// --------------------------------------------------

text = formatTwoColumnSection(
  text,
  "FEATURES",
  "Feature"
);


// --------------------------------------------------
// CLEANUP AGAIN
// --------------------------------------------------

text = text.replace(/\n{3,}/g, "\n\n");

text = text.trim();


// --------------------------------------------------
// ADD HUMAN-IN-THE-LOOP INSTRUCTION
// --------------------------------------------------

text +=
  "\n\n────────────────────────────\n" +
  "*ACTION REQUIRED*\n\n" +
  "Reply with *APPROVE* to approve this PRD.\n" +
  "Or reply with *MODIFY:* followed by your changes.";

return [
  {
    json: {
      slack_message: text
    }
  }
];
